target.css:
:root {
  --paper: #fffdf7;
  --ink: #203638;
  --muted: #68787a;
  --line: #d5dfd7;
  --forest: #276b5b;
  --mint: #dff0df;
  --gold: #d99231;
  --cream: #fff3d6;
}

.tool-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--line);
}

.tool-mark {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  place-items: center;
  background: var(--mint);
  border-radius: 11px;
  font-size: 20px;
}

.heading-group {
  min-width: 0;
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--forest);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
  line-height: 1.2;
}

h1 {
  margin: 0;
  font-size: 20px;
  font-weight: 750;
  line-height: 1.15;
}

.state {
  padding: 5px 8px;
  background: var(--cream);
  border: 1px solid var(--gold);
  border-radius: 999px;
  color: var(--gold);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.loan-details {
  display: grid;
  grid-template-columns: 1.25fr 1fr 0.85fr;
  padding: 14px 18px;
}

.detail {
  min-width: 0;
  margin: 0;
  padding: 0 14px;
  border-left: 1px solid var(--line);
}

.detail:first-child {
  padding-left: 0;
  border-left: 0;
}

.detail:last-child {
  padding-right: 0;
}

dt {
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
}

dd {
  margin: 0;
  font-size: 14px;
  font-weight: 750;
  line-height: 1.25;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 18px;
  background: var(--mint);
}

.return-note {
  margin: 0;
  color: var(--forest);
  font-size: 12px;
  font-weight: 650;
  line-height: 1.3;
}

.action {
  flex: 0 0 auto;
  padding: 7px 11px;
  border: 0;
  border-radius: 8px;
  background: var(--forest);
  color: var(--paper);
  font-size: 12px;
  font-weight: 750;
}
